def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point:
        def __init__(self, *args, **kwargs):
            for i, field in enumerate(fields):
                setattr(self, field, args[i] if i < len(args) else kwargs.get(field))
        def __repr__(self):
            field_values = [f"{field}={getattr(self, field)!r}" for field in fields]
            return f"{name}({', '.join(field_values)})"
    return Point

