def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    full_cmd = commands + args
    if verbose:
        print("Running command: {}".format(" ".join(full_cmd)))
    try:
        if hide_stderr:
            subprocess.check_call(full_cmd, cwd=cwd, env=env, stderr=subprocess.DEVNULL)
